CREATE TABLE "hup_program_history" ("id" TEXT NOT NULL,"company_id" TEXT NOT NULL,"branch_id" TEXT NOT NULL,"program_id" TEXT NOT NULL,"action" TEXT NOT NULL,"reason" TEXT,"actor_id" TEXT NOT NULL,"occurred_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "hup_program_history_pkey" PRIMARY KEY("id"));CREATE INDEX "hup_program_history_idx" ON "hup_program_history"("company_id","branch_id","program_id","occurred_at");ALTER TABLE "hup_program_history" ADD CONSTRAINT "hup_program_history_program_fkey" FOREIGN KEY("program_id","company_id","branch_id") REFERENCES "hup_programs"("id","company_id","branch_id") ON DELETE RESTRICT ON UPDATE CASCADE;
